Translate("ruRU", "ruins-of-lordaeron", {
	title = "Руины Лордерона",
	sections = {
		{
			title = "Обзор",
			text = [=[Над {link:undercity}Подгород{/link}ом лежат разбитые улицы столицы {link:lordaeron}Лордерон{/link}а. {link:forsaken}Отрекшиеся{/link} держат двор перед своими воротами, но за ним большая часть старого города все еще в руках {link:scourge}Плети{/link}. По переулкам бродят безмозглые мертвецы, в развалинах гнездятся {link:ogres}огр{/link}омные пауки, а площади стерегут поганища, сшитые из тел павших. С недавних пор на улицы и на старое кладбище наполз нечестивый туман. Отрекшиеся поднялись наверх, чтобы вернуть себе свой город.]=],
		},
		{
			title = "Истоки",
			text = [=[Здесь была столица королевства {link:lordaeron}Лордерон{/link} до того дня, когда принц {link:arthas-menethil}Артас Менетил{/link} вернулся домой и убил своего отца. {link:scourge}Плеть{/link} разорила город и перебила его жителей, а павшие восстали, чтобы служить Королю-личу. Когда {link:forsaken}Отрекшиеся{/link} вырвались на свободу, они заняли руины и ушли вниз, строить {link:undercity}Подгород{/link}. Сил очистить весь разрушенный город над собой у них не было. Не так давно на город двинулся некрополь {red:naxxramas}Наксрамас{/red}, и бои шли на этих самых улицах. То, что оставила после себя Плеть, никто так и не вычистил.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:forsaken}Отрекшиеся{/link} отбивают свои старые улицы по одной площади. Они теряют солдат, которых некем заменить, ибо гниющая плоть не заживает. Стражи смерти узнали, что туман — дело рук некроманта Рат'маэля, новой силы в рядах Плети. Похоже, он готовит новое нападение. Аптекарям {link:undercity}Подгород{/link}а нужны образцы ядовитых тварей из руин, а паладинам Отрекшихся — конечности павших, чтобы чинить ими своих сородичей.]=],
		},
		{
			title = "Внутри руин",
			text = [=[• {b}Королевская аллея.{/b} У самого входа, где охотится со своим выводком {link:ogres}огр{/link}омная паучиха.
• {b}Рыночная улица.{/b} Открытая площадь старого города, куда мертвецы стекаются волнами.
• {b}{link:lordaeron-graveyard}Кладбище Лордерона{/link}.{/b} Место погребения столицы, ныне окутанное туманом.
• {b}Лордамерский дозор.{/b} В глубине руин, где {link:rath-mael}Рат'маэль{/link} творит свою магию.]=],
		},
		{
			title = "Реликвии мертвых",
			text = [=[Руины полны того, что оставили после себя живые. В щебне лежат солдатские знаки различия и все еще ждут ближайших родственников. Среди камней попадаются гербы старого королевства, и они нужны для истории и Отрекшимся, и жителям {link:stormwind-city}Штормграда{/link}. На кладбище лежит последнее письмо Отрекшегося по имени Эдвард Сердцеплет. Он приходил сюда каждую неделю искать тело своего сына, потерянного, когда {link:arthas-menethil}Артас{/link} сровнял город с землей. Он не вернулся. Как оказалось, его сын выжил. Мальчика отвезли в приют в Штормграде, а позже его усыновила женщина из {link:duskwood}Сумеречного леса{/link}.]=],
		},
		{
			title = "Те, кто здесь обитает",
			text = [=[Паучиха {link:witherfang}Гиблый Клык{/link}, поганище по прозвищу {link:the-baron}Барон{/link}, {link:the-abandoned}Покинутый{/link}, зверь {link:viktor-the-vile}Виктор Мерзкий{/link}, громила {link:bjork}Бьорк{/link} и некромант {link:rath-mael}Рат'маэль{/link} — все они обитают в руинах. Иногда среди них видят призрак капитана {link:lordaeron}Лордерон{/link}а. Солдат {link:alliance}Альянс{/link}а, капитан Трумэн, все еще стоит на посту в руинах и ждет господина, который некоторое время назад бросился в гущу боя и не вернулся.]=],
		},
	},
})

Translate("ruRU", "lordaeron-graveyard", {
